// Stamp Pose Index — EACH mode, authoritative, no $itemIndex fallback
// Safe to use for BOTH "Stamp Pose Index" nodes.

const j = { ...$json };
const b = $binary || {};

function asIntMaybe(v) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.floor(n) : null;
}
function parsePoseFromString(s) {
  if (!s) return null;
  // Matches: pose01 / pose_01 / pose-01 / ..._01.png / /01.png
  const m = String(s).match(/(?:pose[_\- ]?(\d{1,2}))|[_\-\.](\d{1,2})(?:\D|$)|\/(\d{1,2})\.png$/i);
  return m ? asIntMaybe(m[1] || m[2] || m[3]) : null;
}

// 1) Prefer upstream explicit values
let pose =
  asIntMaybe(j.poseNumber) ??
  asIntMaybe(j.currentPoseNumber) ??
  asIntMaybe(j.__meta?.poseNumber);

// 2) If still missing, derive from filenames / recorded indices
if (pose == null) {
  const candidates = [
    j.poseRefName,
    j.poseRefFilename,
    j.poseRef,
    j.poseFileName,
    j.__reorg?.poseFileName,      // from Reorganize Merged Data
    b.pose?.fileName,
    b.pose?.fileNameOriginal,
  ];
  for (const c of candidates) {
    const parsed = parsePoseFromString(c);
    if (parsed != null) { pose = parsed; break; }
  }
  // last resort: explicit numeric index captured upstream (1..12)
  if (pose == null && asIntMaybe(j.__reorg?.fromIndex) != null) {
    pose = asIntMaybe(j.__reorg.fromIndex);
  }
}

// 3) Hard-fail if we still can't determine pose (prevents overwrites)
if (pose == null || pose < 1 || pose > 12) {
  throw new Error('Stamp Pose Index: poseNumber missing/invalid (expected 1..12).');
}

// 4) Clamp + write back (and mirror into __meta)
pose = Math.max(1, Math.min(12, pose));
const out = {
  ...j,
  poseNumber: pose,
  currentPoseNumber: pose,
  index: pose - 1, // optional helper for merges
  __meta: { ...(j.__meta || {}), poseNumber: pose },
};

console.log(`Stamp Pose Index → pose=${pose}`);
return {
  json: out,
  binary: b,
  // preserve pairing if provided upstream
  ...(($input && $input.item && $input.item.pairedItem) ? { pairedItem: $input.item.pairedItem } : {})
};

// Validate Input
// Mode: Run once for EACH item

const j   = $json || {};
const bin = $binary || {};

// --- Helpers ---
function hasBinary(b) {
  if (!b || typeof b !== 'object') return false;
  // n8n binary usually has a .data property; treat presence as signal
  if ('data' in b) return typeof b.data === 'string' ? b.data.length > 0 : !!b.data;
  return true;
}

// Resolve pose number (prefer explicit fields, fallback to index+1), clamp to [1..12]
let poseNum = Number(j.currentPoseNumber ?? j.poseNumber);
if (!Number.isFinite(poseNum)) {
  poseNum = Number.isFinite(Number($itemIndex)) ? ($itemIndex + 1) : NaN;
}
const poseNumValid    = Number.isFinite(poseNum);
const poseNumClamped  = poseNumValid ? Math.max(1, Math.min(12, Math.floor(poseNum))) : poseNum;
const nn              = poseNumValid ? String(poseNumClamped).padStart(2, '0') : '??';
const poseLabel       = `pose-${nn}`;

// --- Validations ---
const problems = [];
if (!hasBinary(bin.character)) problems.push('missing base character (binary.character)');
if (!hasBinary(bin.pose))      problems.push('missing pose reference (binary.pose)');
if (!poseNumValid)             problems.push('poseNumber missing/invalid');
else if (poseNumClamped !== poseNum)
  problems.push(`poseNumber out of range (${poseNum}) → clamped to ${poseNumClamped}`);

if (problems.length) {
  const binKeys = Object.keys(bin || {}).join(', ') || 'none';
  throw new Error(
    'Validate Input: ' + problems.join('; ')
    + ` | poseLabel=${poseLabel}`
    + ` | binary keys=[${binKeys}]`
  );
}

// --- Output (preserve binaries and add normalized fields) ---
const outJson = {
  ...j,
  poseNumber: poseNumClamped,
  currentPoseNumber: poseNumClamped,
  poseLabel,
  __valid: true,
};

return {
  json: outJson,
  binary: bin,
  pairedItem: ($input && $input.item && $input.item.pairedItem) ? $input.item.pairedItem : { item: ($itemIndex ?? 0) },
};

// === CREATE FINAL SUMMARY (robust hash + order propagation + trace fields) ===

const incomingItems = $input.all();
console.log('=== CREATE FINAL SUMMARY ===');
console.log(`Received ${incomingItems.length} items from loop`);

const isBadHash = (h) => !h || h === 'nohash' || h === 'unknown' || typeof h !== 'string' || h.length < 4;

// Upstream nodes
const metaHash = $('Capture Lean Meta').first()?.json?.__meta?.characterHash;
const genNode  = $('Generate Character Hash').first()?.json || {};
const genHash  = genNode?.characterHash;
const upstreamHash = !isBadHash(metaHash) ? metaHash : (!isBadHash(genHash) ? genHash : null);

// Prefer upstream order snapshot, fall back sensibly
const firstItem   = incomingItems[0]?.json || {};
const sourceOrder = Object.keys(genNode).length ? genNode : firstItem;

// IDs
const amazonOrderId =
  genNode?.amazonOrderId ??
  sourceOrder?.amazonOrderId ??
  firstItem?.orderData?.amazonOrderId ??
  firstItem?.amazonOrderId ??
  null;

// Rich fields (prefer Generate Character Hash)
const characterSpecs    = sourceOrder.characterSpecs    ?? {};
const characterHashSpec = sourceOrder.characterHashSpec ?? {};
const bookSpecs         = sourceOrder.bookSpecs         ?? {};
const orderDetails      = sourceOrder.orderDetails      ?? {};
const publicR2Url       = sourceOrder.publicR2Url       ?? firstItem?.publicR2Url ?? 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev';
const templatePath      = sourceOrder.templatePath      ?? firstItem?.templatePath ?? 'templates';

const orderData = {
  amazonOrderId,
  characterHash: upstreamHash || (!isBadHash(sourceOrder.characterHash) ? sourceOrder.characterHash : null),
  characterSpecs,
  characterHashSpec,
  bookSpecs,
  orderDetails,
  publicR2Url,
  templatePath,
  r2BucketName: 'little-hero-assets'
};

console.log('Order data snapshot:', {
  amazonOrderId: orderData.amazonOrderId || 'null',
  characterHash: orderData.characterHash || 'null',
  childName: orderData.characterSpecs?.childName || 'null'
});

// Build normalized submissions array with trace fields
const submissions = incomingItems.map((item, idx) => {
  const j = item.json || {};
  const pose =
    j.__meta?.poseNumber ??
    j.poseNumber ??
    (Number.isFinite(Number(j.currentPoseNumber)) ? Number(j.currentPoseNumber) : (idx + 1));

  // Hash
  const chosenHash = !isBadHash(j.characterHash) ? j.characterHash
                    : (!isBadHash(orderData.characterHash) ? orderData.characterHash
                    : upstreamHash);

  // Paths / URLs
  const storageKey = j.__meta?.storageKey || j.r2Path || null;
  const fileUrl =
    j.fileUrl || j.imageUrl || j.sourceUrl ||
    (publicR2Url && storageKey ? `${publicR2Url.replace(/\/$/, '')}/${String(storageKey).replace(/^\/+/, '')}` : null);

  return {
    poseNumber: pose,
    characterHash: chosenHash || null,

    // Trace
    correlationId: j.correlationId || null,
    generationConfig: j.generationConfig || null,

    // Locations
    storageKey,
    r2Path: j.r2Path || storageKey || null,
    fileUrl,

    // Bria
    briaSource: j.__meta?.briaSource || (fileUrl ? 'url' : (j.extractedImageData ? 'base64' : null)),
    briaStatus: j.briaStatus || j.briaResult?.status || null,
    briaRequestId: j.requestId || j.briaResult?.requestId || null,
    briaStatusUrl: j.statusUrl || j.briaResult?.statusUrl || null,

    // Failure / timing
    failed: !!j.failed,
    submittedAt: j.submittedAt || new Date().toISOString(),

    // Order context
    amazonOrderId: orderData.amazonOrderId || null,
  };
});

const valid = submissions.filter(s => s.briaRequestId && s.briaStatusUrl);
const failed = submissions.length - valid.length;

console.log(`Valid submissions: ${valid.length}`);
console.log(`Failed submissions: ${failed}`);
console.log(`Pose numbers: ${submissions.map(s => s.poseNumber).join(', ')}`);

if (!orderData.amazonOrderId) {
  console.warn('⚠️ amazonOrderId is missing. Ensure Generate Character Hash receives/forwards it.');
}

return [{
  json: {
    totalSubmissions: submissions.length,
    successful: valid.length,
    failed: failed,
    submittedAt: new Date().toISOString(),

    submissions,
    orderData,           // ← CRITICAL for 2B/next workflow
    workflow2AComplete: true
  }
}];

// Make/Ensure Binary for R2 (per-item)
// Ensures there's a binary under `image` and uses a deterministic per-pose filename.
// Force filesystem mode to reduce memory usage
const useFilesystem = true; // Set to true for large files

const j = $json || {};
const b = $binary || {};

// helpers
function clampInt(v, lo=1, hi=99){ v=Number(v); return Number.isFinite(v)?Math.max(lo,Math.min(hi,Math.floor(v))):null; }
function pad2(n){ return String(n).padStart(2,'0'); }
function lastSegment(p){ const s=String(p||''); const i=Math.max(s.lastIndexOf('/'), s.lastIndexOf('\\')); return i>=0 ? s.slice(i+1) : s; }

const poseNum = clampInt(j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber ?? ($itemIndex+1)) || 0;
const NN = pad2(poseNum);
const hash = j.characterHash || j.characterSpecs?.hash || j.__meta?.characterHash || 'nohash';

// Prefer an existing generated image
if (b?.generated) {
  // normalize name (no path) so it’s a stable fallback
  const fname = lastSegment(b.generated.fileName || b.generated.fileNameOriginal || `characters_${hash}_pose${NN}.png`);
  const gen = { ...b.generated, fileName: fname, mimeType: b.generated.mimeType || 'image/png' };
  return { json: j, binary: { ...b, image: gen } };
}

// Already had a generic `image`?
if (b?.image) {
  return { json: j, binary: b };
}

// Build one from base64 if available
let b64 = j.extractedImageData || j.poseBase64 || j.characterBase64 || null;
if (typeof b64 === 'string' && b64.length > 10) {
  let mime = 'image/png';
  const m = b64.match(/^data:(image\/[a-z0-9+.\-]+);base64,(.*)$/i);
  if (m) { mime = m[1]; b64 = m[2]; }
  const buf = Buffer.from(b64, 'base64');
  const bin = await this.helpers.prepareBinaryData(buf, `characters_${hash}_pose${NN}.png`, mime);
  return { json: j, binary: { ...b, image: bin } };
}

// Try URL if present
const url = j.originalImageUrl || j.imageUrl || j.sourceUrl || null;
if (typeof url === 'string' && /^https?:\/\//i.test(url)) {
  const res = await this.helpers.request({ method: 'GET', url, encoding: null, gzip: true });
  const bin = await this.helpers.prepareBinaryData(Buffer.from(res), `characters_${hash}_pose${NN}.png`);
  return { json: j, binary: { ...b, image: bin } };
}

// Otherwise, nothing to upload — mark & pass through
return { json: { ...j, __skipUpload: true } };

// Capture Lean Meta — per-item, upstream-aware, single-object return
// Adds BOTH a canonical storageKey and a unique versionedKey.

const j = $json || {};
const b = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// helpers
function clampInt(v, lo=1, hi=99){ const n=Number(v); return Number.isFinite(n)?Math.max(lo,Math.min(hi,Math.floor(n))):null; }
function pad2(n){ return String(n).padStart(2,'0'); }
function parsePoseFromName(s){ if(!s) return null; const m=String(s).match(/pose[_-]?(\d{1,2})/i); return m?clampInt(m[1]):null; }
function getItem(node){ try{ const a=$items(node,0,$itemIndex); if(a?.[0]) return a[0]; }catch{} try{ const a2=$items(node,runIx); return a2[$itemIndex]||a2[0]||{}; }catch{} return {}; }
function J(node){ return getItem(node).json || {}; }
function B(node,key){ return (getItem(node).binary||{})[key] || null; }

const fromBuild = J('Build Dynamic Pose Prompt');
const fromPrep0 = J('Prepare Gemini (POSE)');
const fromPrepR = J('Prepare Gemini (POSE) — Retry');

let poseNum =
  clampInt(j.poseNumber) ??
  clampInt(j.currentPoseNumber) ??
  clampInt(j.__meta?.poseNumber) ??
  clampInt(fromBuild.poseNumber) ??
  clampInt(fromBuild.currentPoseNumber) ??
  (Number.isFinite(Number(fromBuild.index)) ? clampInt(Number(fromBuild.index)+1) : null) ??
  clampInt(fromPrepR.poseNumber) ??
  clampInt(fromPrep0.poseNumber) ??
  parsePoseFromName(b.pose?.fileName || j.poseRefName || j.poseRefFilename || B('Download pose reference','pose')?.fileName) ??
  clampInt($itemIndex + 1);

if (!poseNum) throw new Error('Capture Lean Meta: poseNumber missing; ensure upstream stamps pose index.');
poseNum = Math.min(12, Math.max(1, poseNum));
const NN = pad2(poseNum);

// character hash
const gen   = J('Generate Character Hash');
const hash  = j.characterHash || j.characterSpecs?.hash || gen.characterHash || null;

// ========================================
// CRITICAL VALIDATION: characterHash must be present
// ========================================
if (!hash || hash === 'nohash' || hash === 'unknown' || (typeof hash === 'string' && hash.trim().length < 4)) {
  console.error('❌ CRITICAL: characterHash missing or invalid in Capture Lean Meta', {
    hasField: !!j.characterHash,
    value: hash,
    specsHash: j.characterSpecs?.hash,
    genHash: gen.characterHash,
    availableJsonFields: Object.keys(j).slice(0, 20),
    itemIndex: $itemIndex
  });
  throw new Error(
    'Capture Lean Meta: characterHash is missing or invalid. ' +
    `Received: "${hash}". ` +
    'Previous nodes (Derive QA Pass, etc.) must preserve characterHash field. ' +
    'Check that "Derive QA Pass" preserves all fields correctly.'
  );
}

// constants
const BASE_PREFIX = 'book-mvp-simple-adventure/order-generated-assets/characters';
const DEFAULT_R2  = 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev';

// derive try/run id (unique per execution)
const tryNum   = clampInt(j.qaRetry ?? j.__meta?.qaRetry ?? 1) || 1;
const tryTag   = pad2(tryNum);
const orderId  = j.amazonOrderId ?? gen.amazonOrderId ?? j.orderData?.amazonOrderId ?? 'unknown-order';
const runStamp = (j.__meta?.runStamp) || new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14);
const runTag   = j.correlationId || j.responseId || `run_${runStamp}`;

// canonical & versioned keys
let storageKey, versionedKey, characterPath;

// Hash is validated, safe to use
characterPath = `${BASE_PREFIX}/${hash}`;
const baseFile = `characters_${hash}_pose${NN}.png`;
storageKey     = `${characterPath}/${baseFile}`;                           // canonical ("latest")
versionedKey   = `${characterPath}/_runs/${runTag}/characters_${hash}_pose${NN}_try${tryTag}.png`; // unique

// merge & return
const outJson = {
  ...j,
  publicR2Url: j.publicR2Url ?? gen.publicR2Url ?? DEFAULT_R2,
  poseNumber: poseNum,
  currentPoseNumber: poseNum,
  characterHash: hash,
  characterPath,
  orderData: {
    ...(j.orderData || {}),
    amazonOrderId: orderId,
    characterHash: hash,
    characterPath,
    r2BucketName: j.orderData?.r2BucketName ?? 'little-hero-assets',
  },
  __meta: {
    ...(j.__meta || {}),
    runStamp,
    poseNumber: poseNum,
    characterHash: hash,
    characterPath,
    storageKey,     // canonical ("latest")
    versionedKey,   // ← use this in the Upload node to avoid overwrites
    captureLeanMeta: {
      resolvedPose: `pose${NN}.png`,
      tryNum, runTag,
      validatedHash: true, // ← added to track that validation passed
      sources: {
        local: { poseNumber: j.poseNumber, currentPoseNumber: j.currentPoseNumber, metaPose: j.__meta?.poseNumber },
        build: { poseNumber: fromBuild.poseNumber, currentPoseNumber: fromBuild.currentPoseNumber, index: fromBuild.index },
        prep0: { poseNumber: fromPrep0.poseNumber },
        prepr:{ poseNumber: fromPrepR.poseNumber },
        parsed: parsePoseFromName(b.pose?.fileName || j.poseRefFilename || j.poseRefName),
        fallbackIndex1: $itemIndex + 1,
      }
    }
  },
};

console.log(`✅ Capture Lean Meta: pose=${poseNum}, hash=${hash.substring(0,8)}..., try=${tryNum}`);

return { json: outJson, binary: b, pairedItem: $input?.item?.pairedItem ?? { item: ($itemIndex ?? 0) } };

parameters.fileName:
={{
  $json.__meta?.versionedKey
  || $json.__meta?.storageKey
  ||
  (() => {
    const slug = s => String(s||'')
      .toLowerCase().replace(/[^a-z0-9._-]+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'');
    const prefix = slug($json.s3Prefix || $json.bookSlug || $json.projectSlug || 'book-mvp-simple-adventure');
    const ch     = slug($json.characterHash || 'nohash');
    const pose   = String($json.poseNumber ?? $json.currentPoseNumber ?? 0).padStart(2,'0');
    return `${prefix}/order-generated-assets/characters/${ch}/characters_${ch}_pose${pose}.png`;
  })()
}}

parameters.jsCode:
// Parse QA Verdict — EACH mode (strip code fences and robustly parse JSON)
// Input: Gemini QA HTTP response (text in candidates[].content.parts[].text)
// Output fields added: qaText (cleaned), qaVerdict (parsed JSON)

const j   = $json || {};
const bin = $binary || {};

// Find the model's text payload anywhere in the response
function findText(obj){
  if (!obj || typeof obj !== 'object') return null;
  if (Array.isArray(obj)){
    for (const v of obj){ const f = findText(v); if (f) return f; }
    return null;
  }
  if (typeof obj.text === 'string') return obj.text;
  if (obj.candidates) return findText(obj.candidates);
  if (obj.content)    return findText(obj.content);
  if (obj.parts)      return findText(obj.parts);
  if (obj[0])         return findText(obj[0]);
  return null;
}

function stripFences(s){
  if (!s) return '';
  let t = String(s).trim();
  // remove leading/trailing code fences like ```json ... ``` or ``` ...
  t = t.replace(/^```[a-zA-Z]*\s*/,'').replace(/```$/,'').trim();
  // also remove stray backticks if any remain
  t = t.replace(/```/g,'').trim();
  return t;
}

function tryParseJsonLoose(s){
  // Try direct JSON.parse first
  try { return JSON.parse(s); } catch {}
  // Try to extract the first {...} block
  const start = s.indexOf('{');
  const end   = s.lastIndexOf('}');
  if (start >= 0 && end > start) {
    const sub = s.slice(start, end + 1);
    try { return JSON.parse(sub); } catch {}
  }
  return null;
}

const rawText = findText(j) || '';
const cleaned = stripFences(rawText);

const verdict = tryParseJsonLoose(cleaned) || {
  pose_score: 0,
  single_subject: false,
  extra_limbs: true,
  bg_white: false,
  leakage_from_pose_ref: true,
  cropped: true,
  notes: 'validator parse error'
};

// Return ONE object (EACH mode)
return {
  json: { 
    ...j,
    qaText: cleaned,
    qaVerdict: verdict
  },
  binary: bin,
  ...( $input?.item?.pairedItem ? { pairedItem: $input.item.pairedItem } : {} ),
};

// Pose QA — Build Request — INITIAL (POSE-FIRST, MINIMAL-PAIR) — EACH
// Filesystem-safe; reads buffers for the CURRENT item; minimal 2-image payload.

// ---------- boot ----------
const jIn  = $json || {};
const bin  = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// ---------- slim any heavy fields (no base64 carried downstream) ----------
function stripInlineDataDeep(o){
  if (!o || typeof o !== 'object') return o;
  if (Array.isArray(o)) return o.map(stripInlineDataDeep);
  const x = {};
  for (const [k,v] of Object.entries(o)) {
    if (k === 'inlineData' && v && typeof v === 'object') {
      const mimeType = v.mimeType || undefined;
      x.inlineData = mimeType ? { mimeType } : {};
    } else {
      x[k] = stripInlineDataDeep(v);
    }
  }
  return x;
}
function slimJson(j){
  const c = { ...(j || {}) };
  delete c.qaRequestBody;
  delete c.requestBody;
  delete c.contents;
  delete c.systemInstruction;
  return stripInlineDataDeep(c);
}
const j = slimJson(jIn);

// ---------- mock/test thresholds ----------
const isMock =
  !!j.__testMode ||
  !!j.__allowTinyImage ||
  String(j.modelVersion || '').toLowerCase().includes('mock');

const minBytes = Number.isFinite(Number(j.minInlineBytes))
  ? Number(j.minInlineBytes)
  : (isMock ? 1 : 100);

// ---------- helpers ----------
function currentIndex(){
  const p = $input?.item?.pairedItem;
  if (p && typeof p.item === 'number') return p.item;
  if (typeof $itemIndex === 'number') return $itemIndex;
  return 0;
}
const idx = currentIndex();

async function readBuffer(key, { allowTiny=false } = {}){
  if (!bin[key]) return null;
  try {
    const buf = await this.helpers.getBinaryDataBuffer(idx, key);
    if (!buf) return null;
    const ok = buf.length >= minBytes || (allowTiny && buf.length > 0);
    return ok ? buf : null;
  } catch { return null; }
}
function toB64(buf){ return buf.toString('base64'); }
function sha1(buf){ return require('crypto').createHash('sha1').update(buf).digest('hex'); }
function mimeFromExt(name=''){
  const n = String(name).toLowerCase();
  if (n.endsWith('.jpg') || n.endsWith('.jpeg')) return 'image/jpeg';
  if (n.endsWith('.webp')) return 'image/webp';
  if (n.endsWith('.png')) return 'image/png';
  return null;
}
function inferMime(b, fallback='image/png'){
  return b?.mimeType || mimeFromExt(b?.fileName || b?.fileNameOriginal) || fallback;
}
function zpad(n, w=2){ const s=String(Math.max(0, Number(n)|0)); return s.length>=w?s:'0'.repeat(w-s.length)+s; }
function looksLikePoseName(name){
  const n = String(name||'').toLowerCase();
  if (/pose[_\-]?\d{1,3}\.(png|jpe?g|webp)$/.test(n)) return true;
  if (/^p[\-_]?\d{1,3}\.(png|jpe?g|webp)$/.test(n))   return true;
  return /(^|\/)pose(\.|_|-|$)/.test(n);
}

function safeItems(nodeName, rIx){ try { return $items(nodeName, 0, rIx) || []; } catch { return []; } }
function preferredIndex(arr){
  const p = $input?.item?.pairedItem?.item;
  const ix = (typeof p === 'number') ? p : (typeof $itemIndex === 'number' ? $itemIndex : 0);
  return (ix>=0 && ix<arr.length) ? ix : 0;
}
function getItemFromNode(nodeName, rIx){
  const arr = safeItems(nodeName, rIx);
  if (!arr.length) return null;
  const ix = preferredIndex(arr);
  return arr[ix] || arr[0] || null;
}

function normalizeBinary(b, fallbackName){
  if (!b) return null;
  return { ...b, mimeType: b.mimeType || 'image/png', fileName: b.fileName || b.fileNameOriginal || fallbackName };
}

function pickPoseFromMap(map, fallbackName){
  if (!map) return null;
  if (map.pose && looksLikePoseName(map.pose.fileName || map.pose.fileNameOriginal || 'pose.png'))
    return normalizeBinary(map.pose, fallbackName);
  for (const k of Object.keys(map)) {
    const b = map[k];
    const name = b?.fileName || b?.fileNameOriginal;
    if (looksLikePoseName(name)) return normalizeBinary(b, fallbackName);
  }
  if (map.pose) return normalizeBinary(map.pose, fallbackName);
  return null;
}
function expectedPoseNames(){
  const n = j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber ?? null;
  if (n == null || Number.isNaN(Number(n))) return [];
  const nn2 = zpad(n,2), nn3 = zpad(n,3);
  return [`pose${nn2}.png`,`pose-${nn2}.png`,`pose_${nn2}.png`,
          `pose${nn3}.png`,`pose-${nn3}.png`,`pose_${nn3}.png`];
}
function posePredicate(b){
  const fileName = (b?.fileName || b?.fileNameOriginal || '').toLowerCase();
  const expect = expectedPoseNames();
  if (expect.length) {
    const nameNoExt = fileName.replace(/\.(png|jpe?g|webp)$/, '');
    for (const exp of expect) {
