  ? `${hashedBase}/${stableName}`                              // canonical "latest"
  : `${nohashBase}/pose${NN}.png`;

const computedVersionedKey = (hash && hash !== 'nohash')
  ? `${hashedBase}/_runs/${runTag}/${versionedName}`           // unique per execution
  : `${nohashBase}/pose${NN}_try${TT}.png`;

// keep existing keys if upstream set them
const existingStorage = out.json.__meta?.storageKey;
const existingVersion = out.json.__meta?.versionedKey;

// normalize binary: keep the **versioned** name for traceability
out.binary.generated = {
  ...gen,
  fileName: versionedName,
  mimeType: gen.mimeType || 'image/png',
  fileExtension: gen.fileExtension || 'png',
};

// 3) annotate JSON (no blow-ups)
out.json.publicR2Url = out.json.publicR2Url || DEFAULT_R2;
out.json.poseNumber = poseNum;
out.json.currentPoseNumber = poseNum;

out.json.__meta = {
  ...(out.json.__meta || {}),
  storageKey:  existingStorage || computedStorageKey,   // canonical
  versionedKey: existingVersion || computedVersionedKey,// unique → use in Upload node
  characterHash: hash,
  poseNumber: poseNum,
  prepareUpload: { versionedName, stableName, keptExistingStorageKey: !!existingStorage, keptExistingVersionedKey: !!existingVersion },
};

return out;

// Derive Pose Identities — EACH mode
// Robustly resolves poseNumber per item (fields → filenames/keys → index+1)

const j   = $json || {};
const bin = $binary || {};

// ---------- helpers ----------
function clampInt(n, lo = 1, hi = 12) {
  n = Number(n);
  return Number.isFinite(n) ? Math.max(lo, Math.min(hi, Math.floor(n))) : null;
}
const POSE_REGEX = /(?:pose[_\- ]?(\d{1,2}))|[_\-\.](\d{1,2})(?:\D|$)|\/(\d{1,2})\.(?:png|jpe?g|webp)$/i;
function parsePoseFromString(s) {
  if (!s) return null;
  const m = String(s).match(POSE_REGEX);
  return m ? clampInt(m[1] || m[2] || m[3]) : null;
}

// Prefer paired index → $itemIndex
const i = ($input?.item?.pairedItem?.item ?? (typeof $itemIndex === 'number' ? $itemIndex : 0));

// priority: explicit fields → URL/key/filename hints → index+1
let poseNum =
  clampInt(j.poseNumber) ??
  clampInt(j.currentPoseNumber) ??
  clampInt(j.__meta?.poseNumber) ??
  parsePoseFromString(j.poseRefKey) ??
  parsePoseFromString(j.poseRefUrl) ??
  parsePoseFromString(j.poseRefName || j.poseRefFilename || j.poseFileName) ??
  parsePoseFromString(bin.pose?.fileName || bin.pose?.fileNameOriginal) ??
  clampInt(i + 1);

if (!poseNum) {
  throw new Error(
    'Derive Pose Identities (EACH): missing poseNumber '
    + '(checked poseNumber/currentPoseNumber/__meta.poseNumber/poseRefKey/poseRefUrl/poseRefName/binary.pose.fileName)'
  );
}

const NN        = String(poseNum).padStart(2, '0');
const poseLabel = `pose-${NN}`;

return {
  json: {
    ...j,
    poseNumber: poseNum,
    currentPoseNumber: poseNum,
    poseIndex: poseNum - 1,
    poseLabel,
    __meta: { ...(j.__meta || {}), poseNumber: poseNum }
  },
  binary: bin,
  pairedItem: $input?.item?.pairedItem ?? { item: i },
};

// 🧪 MOCK: Gemini Image Generation (EACH mode)
// Adds __testMode flags so downstream extractors can be lenient.
// Keeps a realistic Gemini response with a 1x1 transparent PNG.

const j = $json || {};
const b = $binary || {};

// Normalize pose for nicer filenames downstream (optional)
function clamp(n, lo=1, hi=99){ const x = Number(n); return Number.isFinite(x) ? Math.max(lo, Math.min(hi, Math.floor(x))) : null; }
let poseNum = j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber ?? null;
poseNum = clamp(poseNum);

// Real 1x1 transparent PNG (base64)
const TINY_PNG_B64 = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";

// Realistic Gemini-style response
const mockResponse = {
  candidates: [{
    content: { parts: [{ inlineData: { mimeType: "image/png", data: TINY_PNG_B64 } }] },
    finishReason: "STOP",
    safetyRatings: []
  }],
  usageMetadata: { promptTokenCount: 100, candidatesTokenCount: 50, totalTokenCount: 150 },
  modelVersion: "gemini-2.5-flash-image-mock"
};

console.log('🧪 MOCK: Returning fake image for pose', poseNum ?? '?');

return {
  json: {
    // keep upstream context so extractor can name files, etc.
    ...j,
    poseNumber: poseNum ?? j.poseNumber,
    currentPoseNumber: poseNum ?? j.currentPoseNumber,

    // explicit test flags for downstream nodes
    __testMode: true,
    __allowTinyImage: true,
    minInlineBytes: 1,

    // merge the mock Gemini response at top level
    ...mockResponse,
  },
  binary: b,
  pairedItem: $input?.item?.pairedItem ?? { item: ($itemIndex ?? 0) }
};

// 🧪 MOCK: Gemini QA Analysis — PASS (canonical schema for parser)
// Emits a Gemini-style response where `parts[].text` is JSON with the exact fields
// your verdict parser expects. Always PASS unless you override scores in $json.

const j = $json || {};

// Allow tuneable thresholds in tests
const minPoseScore = Number.isFinite(Number(j.qaMinPoseScore)) ? Number(j.qaMinPoseScore) : 0.70;
// You can override with j.mockPoseScore if you want different values per test
const desiredScore = Number.isFinite(Number(j.mockPoseScore)) ? Number(j.mockPoseScore) : 0.95;
// Guarantee pass by being ≥ minPoseScore (with a small cushion)
const poseScore = Math.max(desiredScore, minPoseScore + 0.05);

// Build the EXACT verdict object your parser expects
const verdictObject = {
  pose_score: poseScore,
  single_subject: true,
  extra_limbs: false,
  bg_white: true,
  leakage_from_pose_ref: false,
  cropped: false,
  notes: 'Mock QA - test mode always passes (canonical schema)'
};

// Wrap it like a Gemini response (so your `findText` sees `.text`)
const mockResponse = {
  candidates: [{
    content: {
      parts: [{
        text: JSON.stringify(verdictObject)
      }]
    },
    finishReason: "STOP"
  }],
  usageMetadata: {
    promptTokenCount: 50,
    candidatesTokenCount: 20,
    totalTokenCount: 70
  },
  // optional debug breadcrumb
  mockInfo: {
    poseNumber: j.poseNumber ?? j.currentPoseNumber ?? null,
    minPoseScore,
    poseScore
  }
};

console.log('🧪 MOCK PASS emitted for pose', j.poseNumber ?? j.currentPoseNumber ?? '?', 'score:', poseScore);

// Return SINGLE object (EACH mode)
return {
  json: mockResponse,
  binary: $binary,
  pairedItem: ($input && $input.item && $input.item.pairedItem)
    ? $input.item.pairedItem
    : { item: (typeof $itemIndex === 'number' ? $itemIndex : 0) },
};

