// Restore Binaries After QA HTTP
// HTTP nodes don't preserve binaries - we need to fetch them from upstream

const apiResponse = $input.item.json;
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

// Get binaries from the node that built the QA request
function getItemFromNode(nodeName) {
  try {
    const arr = $items(nodeName, 0, runIx);
    return arr[itemIx] || arr[0] || null;
  } catch {
    return null;
  }
}

// Try to find the binaries from upstream nodes
const binarySources = [
  'Reattach Binaries (For QA)',
  'Pose QA — Build Request',
  'Extract Generated Image — Retry',
  'Drop Pose Payload'
];

let binaries = {};
for (const nodeName of binarySources) {
  const item = getItemFromNode(nodeName);
  if (item && item.binary) {
    binaries = item.binary;
    console.log('Found binaries from: ' + nodeName);
    break;
  }
}

// Also try to get metadata from request builder
const requestBuilder = getItemFromNode('Pose QA — Build Request');
const metadata = requestBuilder ? requestBuilder.json : {};

return {
  json: {
    ...apiResponse,

    // Restore metadata that was lost by HTTP
    characterHash: metadata.characterHash || apiResponse.characterHash,
    poseNumber: metadata.poseNumber || apiResponse.poseNumber,
    correlationId: metadata.correlationId || apiResponse.correlationId,
    qaRetry: metadata.qaRetry || apiResponse.qaRetry,
    orderData: metadata.orderData || apiResponse.orderData,
    __meta: {
      ...(apiResponse.__meta || {}),
      ...(metadata.__meta || {})
    },
  },
  binary: binaries,
  pairedItem: $input.item.pairedItem ? $input.item.pairedItem : { item: itemIx }
};
